  @IsBoolean()
  skipMissingFields?: boolean = false;

  @ApiPropertyOptional({
    description: 'Wait for dynamic form loading',
    default: true,
  })
  @IsOptional()
  @IsBoolean()
  waitForDynamic?: boolean = true;

  @ApiPropertyOptional({
    description: 'Timeout for form filling in seconds',
    default: 30,
  })
