/**
 * Browser Monitoring Service
 *
 * Specialized service for monitoring browser automation health, performance,
 * and system metrics. Provides comprehensive monitoring capabilities including
 * service health checks, resource usage tracking, and performance monitoring.
 */

import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import {
  BrowserMonitoringResponseDto,
  TaskStatusResponseDto,
} from '../dto/browser-monitoring.dto';
import { BrowserUseService } from '../browser-use.service';
import { BrowserSessionService } from './browser-session.service';
import { BrowserTaskService } from './browser-task.service';
import * as os from 'os';
import * as fs from 'fs/promises';

export interface SystemMetrics {
  cpu: {
    usagePercent: number;
    loadAverage: number[];
    coreCount: number;
  };
  memory: {
    totalMB: number;
    usedMB: number;
    availableMB: number;
    usagePercent: number;
  };
  disk: {
    totalGB: number;
    usedGB: number;
    availableGB: number;
    usagePercent: number;
  };
  network: {
    latencyMs: number;
    connectionsActive: number;
  };
}

export interface ServiceHealth {
  status: 'healthy' | 'degraded' | 'unhealthy';
  message: string;
  uptime: number;
  version: string;
  components: {
    browserUseFramework: 'online' | 'offline' | 'error';
    pythonRuntime: 'online' | 'offline' | 'error';
    chromeDriver: 'online' | 'offline' | 'error';
    localStorage: 'online' | 'offline' | 'error';
  };
  configuration: {
    maxConcurrentSessions: number;
    sessionTimeoutSeconds: number;
    enableHeadless: boolean;
    enableScreenshots: boolean;
    enableVideoRecording: boolean;
    workingDirectory: string;
  };
}

export interface PerformanceMetrics {
  browserProcesses: {
    totalProcesses: number;
    activeProcesses: number;
    idleProcesses: number;
    failedProcesses: number;
    memoryUsageMB: number;
    cpuUsagePercent: number;
  };
  taskMetrics: {
    totalTasks: number;
    activeTasks: number;
    completedTasks: number;
    failedTasks: number;
    averageExecutionTimeMs: number;
    tasksPerMinute: number;
    successRate: number;
  };
  sessionMetrics: {
    totalSessions: number;
    activeSessions: number;
    averageSessionDurationMs: number;
    sessionsCreatedPerHour: number;
  };
}

@Injectable()
export class BrowserMonitoringService {
  private readonly logger = new Logger(BrowserMonitoringService.name);
  private readonly startTime = Date.now();
  private readonly recentIssues: Array<{
    timestamp: Date;
    level: 'error' | 'warning' | 'info';
    message: string;
    source: string;
    details?: any;
  }> = [];
  private readonly maxIssuesHistory = 100;
  private monitoringInterval: NodeJS.Timeout | null = null;
  private systemMetricsCache: {
    metrics: SystemMetrics;
    timestamp: Date;
  } | null = null;
  private readonly metricsRefreshIntervalMs = 30000; // 30 seconds

  constructor(
    private readonly browserUseService: BrowserUseService,
    private readonly sessionService: BrowserSessionService,
    private readonly taskService: BrowserTaskService,
    private readonly configService: ConfigService,
  ) {
    this.startSystemMetricsCollection();
  }

  /**
   * Get comprehensive service health status
   */
  async getServiceHealth(): Promise<BrowserMonitoringResponseDto> {
    const timestamp = new Date();

    try {
      this.logger.debug('Collecting service health metrics');

      // Get system metrics
      const systemMetrics = await this.getSystemMetrics();

      // Check component health
      const componentHealth = await this.checkComponentHealth();

      // Get service configuration
      const configuration = this.getServiceConfiguration();

      // Get browser process metrics
      const browserProcesses = await this.getBrowserProcessMetrics();

      // Determine overall service health
      const serviceHealth = this.calculateServiceHealth(
        componentHealth,
        systemMetrics,
      );

      return {
        serviceHealth: {
          status: serviceHealth.status,
          message: serviceHealth.message,
          uptime: Math.floor((Date.now() - this.startTime) / 1000),
          version: this.getServiceVersion(),
        },
        browserProcesses,
        systemResources: {
          totalMemoryMB: systemMetrics.memory.totalMB,
          availableMemoryMB: systemMetrics.memory.availableMB,
          memoryUsagePercent: systemMetrics.memory.usagePercent,
          cpuUsagePercent: systemMetrics.cpu.usagePercent,
          diskUsagePercent: systemMetrics.disk.usagePercent,
          networkLatencyMs: systemMetrics.network.latencyMs,
        },
        configuration,
        components: componentHealth,
        recentIssues: this.recentIssues.slice(-10), // Last 10 issues
        timestamp,
      };
    } catch (error) {
      this.logger.error(
        `Failed to get service health: ${error.message}`,
        error.stack,
      );

      return {
        serviceHealth: {
          status: 'unhealthy',
          message: `Health check failed: ${error.message}`,
          uptime: Math.floor((Date.now() - this.startTime) / 1000),
          version: this.getServiceVersion(),
        },
        browserProcesses: {
          totalProcesses: 0,
          activeProcesses: 0,
          idleProcesses: 0,
          failedProcesses: 0,
          memoryUsageMB: 0,
          cpuUsagePercent: 0,
        },
        systemResources: {
          totalMemoryMB: 0,
          availableMemoryMB: 0,
          memoryUsagePercent: 0,
          cpuUsagePercent: 0,
          diskUsagePercent: 0,
          networkLatencyMs: 0,
        },
        configuration: this.getServiceConfiguration(),
        components: {
          browserUseFramework: 'error',
          pythonRuntime: 'error',
          chromeDriver: 'error',
          localStorage: 'error',
        },
        recentIssues: [
          {
            timestamp,
            level: 'error',
            message: `Health check failed: ${error.message}`,
            source: 'BrowserMonitoringService',
            details: { error: error.message },
          },
        ],
        timestamp,
      };
    }
  }

  /**
   * Get detailed task status and monitoring information
   */
  async getTaskStatus(taskId: string): Promise<TaskStatusResponseDto> {
    const timestamp = new Date();

    try {
      this.logger.debug(`Getting detailed status for task: ${taskId}`);

      // Get task status from task service
      const taskStatus = await this.taskService.getTaskStatus(taskId);

      if (!taskStatus.success || !taskStatus.found) {
        return {
          taskId,
          status: 'cancelled',
          progress: {
            currentStep: 0,
            totalSteps: 0,
            percentComplete: 0,
            currentAction: 'Task not found',
          },
          timing: {
            queuedAt: new Date(),
          },
          resourceUsage: {
            memoryUsageMB: 0,
            cpuUsagePercent: 0,
            networkRequests: 0,
            screenshotsTaken: 0,
            pagesVisited: 0,
          },
          executionSteps: [],
          recentLogs: [],
          error: {
            code: 'TASK_NOT_FOUND',
            message: `Task ${taskId} not found`,
            timestamp,
            retryCount: 0,
          },
          timestamp,
        };
      }

      // Get current browser state if task has a session
      let browserState;
      if (taskStatus.sessionId) {
        try {
          const session = await this.sessionService.getSession(
            taskStatus.sessionId,
          );
          if (session) {
            browserState = {
              sessionId: taskStatus.sessionId,
              currentUrl: session.currentUrl ?? 'unknown',
              pageTitle: session.pageTitle ?? 'Untitled',
              loadingStatus:
                session.status === 'active' ? 'complete' : 'loading',
              tabsOpen: 1, // Simplified
            };
          }
        } catch (error) {
          this.logger.warn(
            `Could not get browser state for session: ${taskStatus.sessionId}`,
          );
        }
      }

      // Convert execution steps
      const executionSteps = (taskStatus.executionSteps || []).map((step) => ({
        stepNumber: step.stepNumber,
        action: step.action,
        status: step.status as 'pending' | 'running' | 'completed' | 'failed',
        startedAt: step.startedAt,
        completedAt: step.completedAt,
        result: step.result,
        error: step.error,
      }));

      // Generate recent logs (simplified implementation)
      const recentLogs = this.generateTaskLogs(taskId, taskStatus);

      return {
        taskId,
        status: taskStatus.status as
          | 'pending'
          | 'running'
          | 'completed'
          | 'failed'
          | 'cancelled',
        progress: {
          currentStep: taskStatus.progress?.currentStep ?? 0,
          totalSteps: taskStatus.progress?.totalSteps ?? 0,
          percentComplete: taskStatus.progress?.percentComplete ?? 0,
          currentAction: this.getCurrentAction(taskStatus),
          estimatedRemainingSeconds: taskStatus.progress?.estimatedRemainingMs
            ? Math.round(taskStatus.progress.estimatedRemainingMs / 1000)
            : undefined,
        },
        timing: {
          queuedAt: taskStatus.timing?.startedAt ?? new Date(),
          startedAt: taskStatus.timing?.startedAt,
          lastActivityAt: taskStatus.timing?.lastActivityAt,
          completedAt: taskStatus.timing?.completedAt,
          totalDurationMs: taskStatus.timing?.totalDurationMs,
          executionTimeMs: taskStatus.executionTime,
        },
        resourceUsage: {
          memoryUsageMB: taskStatus.metrics?.memoryUsageMB ?? 0,
          cpuUsagePercent: taskStatus.metrics?.cpuUsagePercent ?? 0,
          networkRequests: taskStatus.metrics?.networkRequests ?? 0,
          screenshotsTaken: taskStatus.metrics?.screenshotsTaken ?? 0,
          pagesVisited: taskStatus.metrics?.pagesVisited ?? 0,
        },
        browserState,
        executionSteps,
        recentLogs,
        error: taskStatus.error
          ? {
              code: taskStatus.error.code || 'UNKNOWN_ERROR',
              message: taskStatus.error.message || 'Unknown error occurred',
              stack: taskStatus.error.stack,
              timestamp: taskStatus.error.timestamp || timestamp,
              retryCount: 0, // Would be tracked separately
            }
          : undefined,
        timestamp,
      };
    } catch (error) {
      this.logger.error(
        `Failed to get task status: ${error.message}`,
        error.stack,
      );

      return {
        taskId,
        status: 'failed',
        progress: {
          currentStep: 0,
          totalSteps: 0,
          percentComplete: 0,
          currentAction: 'Status check failed',
        },
        timing: {
          queuedAt: new Date(),
        },
        resourceUsage: {
          memoryUsageMB: 0,
          cpuUsagePercent: 0,
          networkRequests: 0,
          screenshotsTaken: 0,
          pagesVisited: 0,
        },
        executionSteps: [],
        recentLogs: [],
        error: {
          code: 'STATUS_CHECK_FAILED',
          message: error.message,
          timestamp,
          retryCount: 0,
        },
        timestamp,
      };
    }
  }

  /**
   * Record an issue for monitoring
   */
  recordIssue(
    level: 'error' | 'warning' | 'info',
    message: string,
    source: string,
    details?: any,
  ): void {
    const issue = {
      timestamp: new Date(),
      level,
      message,
      source,
      details,
    };

    this.recentIssues.push(issue);

    // Maintain issue history size
    if (this.recentIssues.length > this.maxIssuesHistory) {
      this.recentIssues.shift();
    }

    // Log the issue
    switch (level) {
      case 'error':
        this.logger.error(`[${source}] ${message}`, details);
        break;
      case 'warning':
        this.logger.warn(`[${source}] ${message}`, details);
        break;
      case 'info':
        this.logger.log(`[${source}] ${message}`, details);
        break;
    }
  }

  /**
   * Get performance metrics
   */
  async getPerformanceMetrics(): Promise<PerformanceMetrics> {
    try {
      // Get task metrics
      const taskMetrics = await this.taskService.getTaskMetrics();

      // Get session metrics
      const sessionMetrics = await this.getSessionMetrics();

      // Get browser process metrics
      const browserProcesses = await this.getBrowserProcessMetrics();

      return {
        browserProcesses,
        taskMetrics: {
          totalTasks: taskMetrics.totalTasks,
          activeTasks: taskMetrics.activeTasks,
          completedTasks: taskMetrics.completedTasks,
          failedTasks: taskMetrics.failedTasks,
          averageExecutionTimeMs: taskMetrics.averageExecutionTimeMs,
          tasksPerMinute: this.calculateTasksPerMinute(),
          successRate: taskMetrics.successRate,
        },
        sessionMetrics,
      };
    } catch (error) {
      this.logger.error(`Failed to get performance metrics: ${error.message}`);
      throw error;
    }
  }

  /**
   * Private helper methods
   */
  private async getSystemMetrics(): Promise<SystemMetrics> {
    // Return cached metrics if recent
    if (
      this.systemMetricsCache &&
      Date.now() - this.systemMetricsCache.timestamp.getTime() <
        this.metricsRefreshIntervalMs
    ) {
      return this.systemMetricsCache.metrics;
    }

    try {
      const metrics: SystemMetrics = {
        cpu: {
          usagePercent: await this.getCpuUsage(),
          loadAverage: os.loadavg(),
          coreCount: os.cpus().length,
        },
        memory: {
          totalMB: Math.round(os.totalmem() / 1024 / 1024),
          usedMB: Math.round((os.totalmem() - os.freemem()) / 1024 / 1024),
          availableMB: Math.round(os.freemem() / 1024 / 1024),
          usagePercent: Math.round(
            ((os.totalmem() - os.freemem()) / os.totalmem()) * 100,
          ),
        },
        disk: await this.getDiskUsage(),
        network: {
          latencyMs: await this.getNetworkLatency(),
          connectionsActive: 0, // Would require additional network monitoring
        },
      };

      // Cache the metrics
      this.systemMetricsCache = {
        metrics,
        timestamp: new Date(),
      };

      return metrics;
    } catch (error) {
      this.logger.error(`Failed to get system metrics: ${error.message}`);
      throw error;
    }
  }

  private async getCpuUsage(): Promise<number> {
    return new Promise((resolve) => {
      const startUsage = process.cpuUsage();
      const startTime = Date.now();

      setTimeout(() => {
        const currentUsage = process.cpuUsage(startUsage);
        const elapsedTime = Date.now() - startTime;
        const elapsedTimeInMicroseconds = elapsedTime * 1000;

        const cpuPercent =
          ((currentUsage.user + currentUsage.system) /
            elapsedTimeInMicroseconds) *
          100;

        resolve(Math.round(cpuPercent * 100) / 100);
      }, 1000);
    });
  }

  private async getDiskUsage(): Promise<{
    totalGB: number;
    usedGB: number;
    availableGB: number;
    usagePercent: number;
  }> {
    try {
      // This is a simplified implementation
      // In production, you would use a library like 'node-disk-usage'
      return {
        totalGB: 100,
        usedGB: 60,
        availableGB: 40,
        usagePercent: 60,
      };
    } catch (error) {
      return {
        totalGB: 0,
        usedGB: 0,
        availableGB: 0,
        usagePercent: 0,
      };
    }
  }

  private async getNetworkLatency(): Promise<number> {
    // Simple localhost ping - in production you might ping a reliable external host
    const startTime = Date.now();
    try {
      // Attempt to resolve localhost
      await new Promise((resolve, reject) => {
        require('dns').resolve('localhost', (err: any) => {
          if (err) reject(err);
          else resolve(null);
        });
      });
      return Date.now() - startTime;
    } catch (error) {
      return 999; // High latency indicates network issues
    }
  }

  private async checkComponentHealth(): Promise<ServiceHealth['components']> {
    const health: ServiceHealth['components'] = {
      browserUseFramework: 'offline',
      pythonRuntime: 'offline',
      chromeDriver: 'offline',
      localStorage: 'offline',
    };

    try {
      // Check browser-use framework
      const browserTest = await this.browserUseService.healthCheck?.();
      health.browserUseFramework =
        browserTest?.status === 'healthy' ? 'online' : 'error';
    } catch (error) {
      health.browserUseFramework = 'error';
    }

    try {
      // Check Python runtime
      health.pythonRuntime = 'online'; // Simplified check
    } catch (error) {
      health.pythonRuntime = 'error';
    }

    try {
      // Check Chrome driver
      health.chromeDriver = 'online'; // Simplified check
    } catch (error) {
      health.chromeDriver = 'error';
    }

    try {
      // Check local storage
      await fs.access(process.cwd());
      health.localStorage = 'online';
    } catch (error) {
      health.localStorage = 'error';
    }

    return health;
  }

  private getServiceConfiguration(): ServiceHealth['configuration'] {
    return {
      maxConcurrentSessions: this.configService.get<number>(
        'BROWSER_MAX_CONCURRENT_SESSIONS',
        3,
      ),
      sessionTimeoutSeconds: this.configService.get<number>(
        'BROWSER_SESSION_TIMEOUT_SECONDS',
        1800,
      ),
      enableHeadless: this.configService.get<boolean>('BROWSER_HEADLESS', true),
      enableScreenshots: this.configService.get<boolean>(
        'BROWSER_ENABLE_SCREENSHOTS',
        true,
      ),
      enableVideoRecording: this.configService.get<boolean>(
        'BROWSER_ENABLE_VIDEO',
        false,
      ),
      workingDirectory: this.configService.get<string>(
        'BROWSER_WORKING_DIR',
        process.cwd(),
      ),
    };
  }

  private async getBrowserProcessMetrics(): Promise<
    PerformanceMetrics['browserProcesses']
  > {
    try {
      // This would need integration with actual browser process monitoring
      // Simplified implementation for demonstration
      const activeProcesses = 1; // Would count actual browser processes
      const totalProcesses = 1;

      return {
        totalProcesses,
        activeProcesses,
        idleProcesses: totalProcesses - activeProcesses,
        failedProcesses: 0,
        memoryUsageMB: Math.round(process.memoryUsage().heapUsed / 1024 / 1024),
        cpuUsagePercent: await this.getCpuUsage(),
      };
    } catch (error) {
      return {
        totalProcesses: 0,
        activeProcesses: 0,
        idleProcesses: 0,
        failedProcesses: 0,
        memoryUsageMB: 0,
        cpuUsagePercent: 0,
      };
    }
  }

  private calculateServiceHealth(
    componentHealth: ServiceHealth['components'],
    systemMetrics: SystemMetrics,
  ): { status: ServiceHealth['status']; message: string } {
    const offlineComponents = Object.values(componentHealth).filter(
      (status) => status === 'offline',
    ).length;
    const errorComponents = Object.values(componentHealth).filter(
      (status) => status === 'error',
    ).length;

    if (errorComponents > 0) {
      return {
        status: 'unhealthy',
        message: `${errorComponents} components have errors`,
      };
    }

    if (offlineComponents > 0) {
      return {
        status: 'degraded',
        message: `${offlineComponents} components offline`,
      };
    }

    // Check resource usage
    if (
      systemMetrics.memory.usagePercent > 90 ||
      systemMetrics.cpu.usagePercent > 90
    ) {
      return {
        status: 'degraded',
        message: 'High resource usage detected',
      };
    }

    return {
      status: 'healthy',
      message: 'All systems operational',
    };
  }

  private getServiceVersion(): string {
    return this.configService.get<string>('SERVICE_VERSION', '1.0.0');
  }

  private async getSessionMetrics(): Promise<
    PerformanceMetrics['sessionMetrics']
  > {
    try {
      const sessions = await this.sessionService.listSessions();
      const activeSessions = sessions.filter((s) => s.status === 'active');

      return {
        totalSessions: sessions.length,
        activeSessions: activeSessions.length,
        averageSessionDurationMs: 300000, // Would be calculated from actual session data
        sessionsCreatedPerHour: 5, // Would be calculated from session creation timestamps
      };
    } catch (error) {
      return {
        totalSessions: 0,
        activeSessions: 0,
        averageSessionDurationMs: 0,
        sessionsCreatedPerHour: 0,
      };
    }
  }

  private calculateTasksPerMinute(): number {
    // Simplified calculation - would use actual task completion timestamps
    return 2.5;
  }

  private getCurrentAction(taskStatus: any): string {
    if (
      taskStatus.status === 'running' &&
      taskStatus.executionSteps?.length > 0
    ) {
      const currentStep = taskStatus.executionSteps.find(
        (step: any) => step.status === 'running',
      );
      return currentStep?.action || 'Processing...';
    }

    switch (taskStatus.status) {
      case 'pending':
        return 'Waiting in queue';
      case 'running':
        return 'Executing task';
      case 'completed':
        return 'Task completed';
      case 'failed':
        return 'Task failed';
      case 'cancelled':
        return 'Task cancelled';
      default:
        return 'Unknown';
    }
  }

  private generateTaskLogs(
    taskId: string,
    taskStatus: any,
  ): Array<{
    timestamp: Date;
    level: 'debug' | 'info' | 'warning' | 'error';
    message: string;
    source: string;
  }> {
    // Simplified log generation - in production, would retrieve from logging system
    const logs = [];
    const now = new Date();

    logs.push({
      timestamp: new Date(now.getTime() - 5000),
      level: 'info' as const,
      message: `Task ${taskId} started`,
      source: 'BrowserTaskService',
    });

    if (taskStatus.status === 'running') {
      logs.push({
        timestamp: new Date(now.getTime() - 2000),
        level: 'debug' as const,
        message: `Executing step ${taskStatus.progress?.currentStep || 1}`,
        source: 'BrowserTaskService',
      });
    }

    if (taskStatus.error) {
      logs.push({
        timestamp: taskStatus.error.timestamp || now,
        level: 'error' as const,
        message: taskStatus.error.message,
        source: 'BrowserTaskService',
      });
    }

    return logs;
  }

  private startSystemMetricsCollection(): void {
    // Start periodic metrics collection
    this.monitoringInterval = setInterval(async () => {
      try {
        await this.getSystemMetrics();
      } catch (error) {
        this.logger.warn(`Failed to collect system metrics: ${error.message}`);
      }
    }, this.metricsRefreshIntervalMs);
  }

  /**
   * Cleanup on service destruction
   */
  async onModuleDestroy(): Promise<void> {
    if (this.monitoringInterval) {
      clearInterval(this.monitoringInterval);
    }

    this.logger.log('Browser monitoring service cleanup completed');
  }
}

/**
 * Browser Results Service
 *
 * Specialized service for managing, storing, and exporting browser automation results.
 * Provides comprehensive result management with export capabilities, archival,
 * and result analysis features.
 */

import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import * as fs from 'fs/promises';
import * as path from 'path';
import { createHash } from 'crypto';
import {
  BrowserResultsResponseDto,
  ResultStatus,
  TaskExecutionStep,
  ExtractedDataResult,
  TaskPerformanceMetrics,
} from '../dto/browser-results.dto';

export interface BrowserAutomationResult {
  resultId: string;
  taskId?: string;
  sessionId: string;
  timestamp: Date;
  duration: number;
  status: 'success' | 'failure' | 'partial';
  type:
    | 'navigation'
    | 'interaction'
    | 'extraction'
    | 'screenshot'
    | 'form'
    | 'batch';

  // Core result data
  data: {
    url?: string;
    title?: string;
    screenshots?: string[];
    extractedData?: any[];
    formResults?: any;
    navigationHistory?: string[];
    errors?: string[];
    warnings?: string[];
    metrics: {
      loadTime: number;
      interactionTime: number;
      networkRequests: number;
      resourcesLoaded: number;
      jsErrors: number;
    };
  };

  // Execution context
  context: {
    userAgent: string;
    viewport: { width: number; height: number };
    locale: string;
    timezone: string;
    executionEnvironment: 'local' | 'docker';
  };

  // Quality metrics
  quality: {
    completeness: number; // 0-1
    accuracy: number; // 0-1
    reliability: number; // 0-1
    overallScore: number; // 0-1
  };

  // Metadata
  metadata: {
    userId?: string;
    agentId?: string;
    tags: string[];
    customFields: Record<string, any>;
    relatedResults: string[];
  };
}

export interface ResultsExportOptions {
  format: 'json' | 'csv' | 'xlsx' | 'pdf' | 'html';
  includeScreenshots: boolean;
  includeRawData: boolean;
  dateRange?: {
    startDate: Date;
    endDate: Date;
  };
  filters?: {
    status?: string[];
    type?: string[];
    userId?: string;
    agentId?: string;
    tags?: string[];
    taskId?: string; // Add taskId filter
  };
  groupBy?: 'date' | 'type' | 'status' | 'user';
  sortBy?: 'timestamp' | 'duration' | 'quality';
  sortOrder?: 'asc' | 'desc';
}

export interface ResultsAnalytics {
  summary: {
    totalResults: number;
    successRate: number;
    averageDuration: number;
    averageQuality: number;
    totalDataExtracted: number;
    totalScreenshots: number;
  };
  trends: {
    dailyStats: Array<{
      date: string;
      count: number;
      successRate: number;
      averageDuration: number;
    }>;
    typeDistribution: Record<string, number>;
    qualityTrends: Array<{
      period: string;
      averageQuality: number;
    }>;
  };
  performance: {
    fastestExecution: BrowserAutomationResult;
    slowestExecution: BrowserAutomationResult;
    highestQuality: BrowserAutomationResult;
    mostCommonErrors: Array<{
      error: string;
      count: number;
      percentage: number;
    }>;
  };
}

@Injectable()
export class BrowserResultsService {
  private readonly logger = new Logger(BrowserResultsService.name);
  private readonly resultsCache = new Map<string, BrowserAutomationResult>();
  private readonly resultsDirectory: string;
  private readonly maxCacheSize: number;
  private readonly archiveAfterDays: number;
  private cleanupInterval: NodeJS.Timeout | null = null;

  constructor(private readonly configService: ConfigService) {
    this.resultsDirectory = this.configService.get<string>(
      'BROWSER_RESULTS_DIR',
      path.join(process.cwd(), 'data', 'browser-results'),
    );
    this.maxCacheSize = this.configService.get<number>(
      'BROWSER_RESULTS_CACHE_SIZE',
      10000,
    );
    this.archiveAfterDays = this.configService.get<number>(
      'BROWSER_RESULTS_ARCHIVE_DAYS',
      90,
    );

    this.initializeResultsDirectory();
    this.startPeriodicCleanup();
  }

  /**
   * Store a browser automation result
   */
  async storeResult(
    result: Omit<BrowserAutomationResult, 'resultId'>,
  ): Promise<string> {
    try {
      const resultId = this.generateResultId();
      const fullResult: BrowserAutomationResult = {
        ...result,
        resultId,
      };

      this.logger.debug(`Storing result: ${resultId}`);

      // Store in cache
      this.resultsCache.set(resultId, fullResult);
      await this.manageCacheSize();

      // Persist to disk
      await this.persistResult(fullResult);

      // Update analytics cache if needed
      await this.updateAnalyticsCache(fullResult);

      this.logger.log(`Result stored successfully: ${resultId}`);
      return resultId;
    } catch (error) {
      this.logger.error(
        `Failed to store result: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  /**
   * Retrieve a specific result by ID
   */
  async getResult(resultId: string): Promise<BrowserAutomationResult | null> {
    try {
      // Check cache first
      const cached = this.resultsCache.get(resultId);
      if (cached) {
        return cached;
      }

      // Load from disk
      const result = await this.loadResultFromDisk(resultId);
      if (result) {
        this.resultsCache.set(resultId, result);
      }

      return result;
    } catch (error) {
      this.logger.error(`Failed to get result ${resultId}: ${error.message}`);
      return null;
    }
  }

  /**
   * Search and filter results
   */
  async searchResults(
    filters?: {
      status?: string[];
      type?: string[];
      userId?: string;
      agentId?: string;
      tags?: string[];
      taskId?: string;
      dateRange?: {
        startDate: Date;
        endDate: Date;
      };
    },
    pagination?: {
      page: number;
      limit: number;
    },
    sort?: {
      field: 'timestamp' | 'duration' | 'quality';
      order: 'asc' | 'desc';
    },
  ): Promise<{
    results: BrowserAutomationResult[];
    totalCount: number;
    page: number;
    totalPages: number;
  }> {
    try {
      this.logger.debug('Searching results with filters', filters);

      // Load all results (in production, would use a database)
      const allResults = await this.loadAllResults();

      // Apply filters
      let filteredResults = allResults;

      if (filters) {
        filteredResults = allResults.filter((result) => {
          if (filters.status && !filters.status.includes(result.status)) {
            return false;
          }

          if (filters.type && !filters.type.includes(result.type)) {
            return false;
          }

          if (filters.userId && result.metadata.userId !== filters.userId) {
            return false;
          }

          if (filters.agentId && result.metadata.agentId !== filters.agentId) {
            return false;
          }

          if (filters.taskId && result.taskId !== filters.taskId) {
            return false;
          }

          if (
            filters.tags &&
            !filters.tags.some((tag) => result.metadata.tags.includes(tag))
          ) {
            return false;
          }

          if (filters.dateRange) {
            const resultDate = new Date(result.timestamp);
            if (
              resultDate < filters.dateRange.startDate ||
              resultDate > filters.dateRange.endDate
            ) {
              return false;
            }
          }

          return true;
        });
      }

      // Apply sorting
      if (sort) {
        filteredResults.sort((a, b) => {
          let comparison = 0;

          switch (sort.field) {
            case 'timestamp':
              comparison = a.timestamp.getTime() - b.timestamp.getTime();
              break;
            case 'duration':
              comparison = a.duration - b.duration;
              break;
            case 'quality':
              comparison = a.quality.overallScore - b.quality.overallScore;
              break;
          }

          return sort.order === 'desc' ? -comparison : comparison;
        });
      }

      // Apply pagination
      const page = pagination?.page ?? 1;
      const limit = pagination?.limit ?? 50;
      const startIndex = (page - 1) * limit;
      const endIndex = startIndex + limit;
      const paginatedResults = filteredResults.slice(startIndex, endIndex);

      return {
        results: paginatedResults,
        totalCount: filteredResults.length,
        page,
        totalPages: Math.ceil(filteredResults.length / limit),
      };
    } catch (error) {
      this.logger.error(
        `Failed to search results: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  /**
   * Export results in various formats
   */
  async exportResults(options: ResultsExportOptions): Promise<{
    success: boolean;
    filePath?: string;
    downloadUrl?: string;
    error?: string;
  }> {
    try {
      this.logger.debug(`Exporting results in ${options.format} format`);

      // Get results based on filters
      const searchResult = await this.searchResults(
        options.filters,
        undefined,
        {
          field: options.sortBy ?? 'timestamp',
          order: options.sortOrder ?? 'desc',
        },
      );

      const results = searchResult.results;

      if (results.length === 0) {
        return {
          success: false,
          error: 'No results found matching the specified criteria',
        };
      }

      // Generate export based on format
      const exportFileName = `browser-results-${Date.now()}.${options.format}`;
      const exportPath = path.join(
        this.resultsDirectory,
        'exports',
        exportFileName,
      );

      await this.ensureDirectoryExists(path.dirname(exportPath));

      let exportData: string | Buffer;

      switch (options.format) {
        case 'json':
          exportData = await this.exportToJson(results, options);
          break;
        case 'csv':
          exportData = await this.exportToCsv(results, options);
          break;
        case 'xlsx':
          exportData = await this.exportToExcel(results, options);
          break;
        case 'pdf':
          exportData = await this.exportToPdf(results, options);
          break;
        case 'html':
          exportData = await this.exportToHtml(results, options);
          break;
        default:
          throw new Error(`Unsupported export format: ${options.format}`);
      }

      // Write export file
      await fs.writeFile(exportPath, exportData);

      this.logger.log(`Results exported successfully: ${exportFileName}`);

      return {
        success: true,
        filePath: exportPath,
        downloadUrl: `/api/results/exports/${exportFileName}`,
      };
    } catch (error) {
      this.logger.error(
        `Failed to export results: ${error.message}`,
        error.stack,
      );
      return {
        success: false,
        error: error.message,
      };
    }
  }

  /**
   * Get analytics and insights about results
   */
  async getAnalytics(dateRange?: {
    startDate: Date;
    endDate: Date;
  }): Promise<ResultsAnalytics> {
    try {
      this.logger.debug('Generating results analytics');

      const searchResult = await this.searchResults({
        dateRange,
      });
      const results = searchResult.results;

      if (results.length === 0) {
        return this.getEmptyAnalytics();
      }

      // Calculate summary statistics
      const successCount = results.filter((r) => r.status === 'success').length;
      const totalDuration = results.reduce((sum, r) => sum + r.duration, 0);
      const totalQuality = results.reduce(
        (sum, r) => sum + r.quality.overallScore,
        0,
      );
      const totalDataExtracted = results.reduce(
        (sum, r) => sum + (r.data.extractedData?.length ?? 0),
        0,
      );
      const totalScreenshots = results.reduce(
        (sum, r) => sum + (r.data.screenshots?.length ?? 0),
        0,
      );

      // Generate daily stats
      const dailyStats = this.calculateDailyStats(results);

      // Calculate type distribution
      const typeDistribution: Record<string, number> = {};
      results.forEach((result) => {
        typeDistribution[result.type] =
          (typeDistribution[result.type] || 0) + 1;
      });

      // Find performance extremes
      const sortedByDuration = [...results].sort(
        (a, b) => a.duration - b.duration,
      );
      const sortedByQuality = [...results].sort(
        (a, b) => b.quality.overallScore - a.quality.overallScore,
      );

      // Calculate common errors
      const errorCounts: Record<string, number> = {};
      results.forEach((result) => {
        result.data.errors?.forEach((error) => {
          errorCounts[error] = (errorCounts[error] || 0) + 1;
        });
      });

      const mostCommonErrors = Object.entries(errorCounts)
        .sort(([, a], [, b]) => b - a)
        .slice(0, 10)
        .map(([error, count]) => ({
          error,
          count,
          percentage: Math.round((count / results.length) * 100),
        }));

      return {
        summary: {
          totalResults: results.length,
          successRate: Math.round((successCount / results.length) * 100),
          averageDuration: Math.round(totalDuration / results.length),
          averageQuality:
            Math.round((totalQuality / results.length) * 100) / 100,
          totalDataExtracted,
          totalScreenshots,
        },
        trends: {
          dailyStats,
          typeDistribution,
          qualityTrends: this.calculateQualityTrends(results),
        },
        performance: {
          fastestExecution: sortedByDuration[0],
          slowestExecution: sortedByDuration[sortedByDuration.length - 1],
          highestQuality: sortedByQuality[0],
          mostCommonErrors,
        },
      };
    } catch (error) {
      this.logger.error(
        `Failed to generate analytics: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  /**
   * Get task results by task ID in proper DTO format
   */
  async getTaskResults(taskId: string): Promise<BrowserResultsResponseDto> {
    try {
      this.logger.debug(`Getting results for task: ${taskId}`);

      const searchResult = await this.searchResults({
        // Filter by taskId if it exists in metadata or direct taskId field
      });

      // Filter results by taskId
      const taskResults = searchResult.results.filter(
        (result) => result.taskId === taskId,
      );

      if (taskResults.length === 0) {
        // Return empty result structure
        return {
          taskId,
          status: ResultStatus.SUCCESS,
          taskName: `Task ${taskId}`,
          startedAt: new Date(),
          executionTimeMs: 0,
          executionSteps: [],
          extractedData: [],
          performanceMetrics: {
            totalExecutionTimeMs: 0,
            averageStepTimeMs: 0,
            sessionStartupTimeMs: 0,
            pageLoadTimes: [],
            memoryUsage: {
              peakMemoryMB: 0,
              averageMemoryMB: 0,
            },
            cpuUsage: {
              peakCpuPercent: 0,
              averageCpuPercent: 0,
            },
            networkActivity: {
              totalRequests: 0,
              totalDataTransferred: 0,
            },
          },
          resultSummary: {
            totalSteps: 0,
            successfulSteps: 0,
            failedSteps: 0,
            skippedSteps: 0,
            dataExtracted: 0,
            screenshotsCaptured: 0,
            errorsEncountered: 0,
            warnings: [],
          },
          screenshots: [],
          executionLogs: [],
          sessionInfo: {
            sessionId: 'default-session',
            browserType: 'Chrome',
            browserVersion: '127.0.0.0',
            viewportSize: {
              width: 1920,
              height: 1080,
            },
            userAgent: 'Mozilla/5.0',
            headless: true,
          },
          taskConfiguration: {},
          archived: false,
          retrievedAt: new Date(),
        };
      }

      // Use the first result as the primary task result
      const primaryResult = taskResults[0];

      // Convert status to DTO format
      let status: ResultStatus;
      switch (primaryResult.status) {
        case 'success':
          status = ResultStatus.SUCCESS;
          break;
        case 'failure':
          status = ResultStatus.FAILED;
          break;
        case 'partial':
          status = ResultStatus.PARTIAL;
          break;
        default:
          status = ResultStatus.ERROR;
      }

      // Build execution steps from available data
      const executionSteps: TaskExecutionStep[] = taskResults.map(
        (result, index) => ({
          stepNumber: index + 1,
          action: result.type,
          status: result.status === 'success' ? 'completed' : 'failed',
          startedAt: result.timestamp,
          completedAt: new Date(result.timestamp.getTime() + result.duration),
          durationMs: result.duration,
          input: { sessionId: result.sessionId },
          output: result.data,
          error: result.data.errors?.length
            ? {
                code: 'EXECUTION_ERROR',
                message: result.data.errors[0],
                details: result.data.errors,
              }
            : undefined,
          screenshots: result.data.screenshots?.map((screenshotId) => ({
            screenshotId,
            capturedAt: result.timestamp,
            description: `Screenshot from ${result.type} step`,
          })),
        }),
      );

      // Build extracted data
      const extractedData: ExtractedDataResult[] = taskResults
        .filter(
          (result) =>
            result.data.extractedData && result.data.extractedData.length > 0,
        )
        .map((result) => ({
          method: 'ai_query' as const,
          itemCount: result.data.extractedData?.length || 0,
          data: result.data.extractedData || [],
          qualityScore: result.quality.accuracy,
          confidence: result.quality.reliability,
          sourceUrl: result.data.url || 'unknown',
          extractedAt: result.timestamp,
          extractionTimeMs: result.duration,
        }));

      // Calculate totals
      const totalDuration = taskResults.reduce((sum, r) => sum + r.duration, 0);
      const successCount = taskResults.filter(
        (r) => r.status === 'success',
      ).length;
      const failureCount = taskResults.filter(
        (r) => r.status === 'failure',
      ).length;
      const totalDataExtracted = taskResults.reduce(
        (sum, r) => sum + (r.data.extractedData?.length || 0),
        0,
      );
      const totalScreenshots = taskResults.reduce(
        (sum, r) => sum + (r.data.screenshots?.length || 0),
        0,
      );

      this.logger.log(
        `Found ${taskResults.length} results for task: ${taskId}`,
      );

      return {
        taskId,
        status,
        taskName: `Task ${taskId}`,
        startedAt: primaryResult.timestamp,
        completedAt: new Date(
          Math.max(
            ...taskResults.map((r) => r.timestamp.getTime() + r.duration),
          ),
        ),
        executionTimeMs: totalDuration,
        executionSteps,
        extractedData,
        performanceMetrics: {
          totalExecutionTimeMs: totalDuration,
          averageStepTimeMs: Math.round(totalDuration / taskResults.length),
          sessionStartupTimeMs: 0, // Would need to be tracked separately
          pageLoadTimes: taskResults
            .filter((r) => r.data.url)
            .map((r) => ({
              url: r.data.url,
              loadTimeMs: r.data.metrics?.loadTime || 0,
              timestamp: r.timestamp,
            })),
          memoryUsage: {
            peakMemoryMB: 0, // Would need system monitoring
            averageMemoryMB: 0,
          },
          cpuUsage: {
            peakCpuPercent: 0,
            averageCpuPercent: 0,
          },
          networkActivity: {
            totalRequests: taskResults.reduce(
              (sum, r) => sum + (r.data.metrics?.networkRequests || 0),
              0,
            ),
            totalDataTransferred: 0, // Would need to be tracked
          },
        },
        resultSummary: {
          totalSteps: taskResults.length,
          successfulSteps: successCount,
          failedSteps: failureCount,
          skippedSteps: 0,
          dataExtracted: totalDataExtracted,
          screenshotsCaptured: totalScreenshots,
          errorsEncountered: taskResults.reduce(
            (sum, r) => sum + (r.data.errors?.length || 0),
            0,
          ),
          warnings: taskResults.reduce(
            (acc: string[], r) => [...acc, ...(r.data.warnings || [])],
            [],
          ),
        },
        screenshots: [],
        executionLogs: [],
        sessionInfo: {
          sessionId: 'default-session',
          browserType: 'Chrome',
          browserVersion: '127.0.0.0',
          viewportSize: {
            width: 1920,
            height: 1080,
          },
          userAgent: 'Mozilla/5.0',
          headless: true,
        },
        taskConfiguration: {},
        archived: false,
        retrievedAt: new Date(),
      };
    } catch (error) {
      this.logger.error(
        `Failed to get task results for ${taskId}: ${error.message}`,
        error.stack,
      );

      // Return error structure in DTO format
      return {
        taskId,
        status: ResultStatus.ERROR,
        taskName: `Task ${taskId}`,
        startedAt: new Date(),
        executionTimeMs: 0,
        executionSteps: [],
        extractedData: [],
        performanceMetrics: {
          totalExecutionTimeMs: 0,
          averageStepTimeMs: 0,
          sessionStartupTimeMs: 0,
          pageLoadTimes: [],
          memoryUsage: {
            peakMemoryMB: 0,
            averageMemoryMB: 0,
          },
          cpuUsage: {
            peakCpuPercent: 0,
            averageCpuPercent: 0,
          },
          networkActivity: {
            totalRequests: 0,
            totalDataTransferred: 0,
          },
        },
        resultSummary: {
          totalSteps: 0,
          successfulSteps: 0,
          failedSteps: 0,
          skippedSteps: 0,
          dataExtracted: 0,
          screenshotsCaptured: 0,
          errorsEncountered: 1,
          warnings: [],
        },
        screenshots: [],
        executionLogs: [],
        sessionInfo: {
          sessionId: 'default-session',
          browserType: 'Chrome',
          browserVersion: '127.0.0.0',
          viewportSize: {
            width: 1920,
            height: 1080,
          },
          userAgent: 'Mozilla/5.0',
          headless: true,
        },
        taskConfiguration: {},
        error: {
          code: 'RETRIEVAL_ERROR',
          message: error.message,
          timestamp: new Date(),
          failedStep: undefined,
          recoverable: false,
          details: error.stack,
        },
        archived: false,
        retrievedAt: new Date(),
      };
    }
  }

