/**
 * Browser Screenshot Service
 *
 * Specialized service for capturing, processing, and managing screenshots
 * from browser automation tasks. Provides comprehensive screenshot functionality
 * with optimization, annotation, and comparison capabilities.
 */

import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import * as fs from 'fs/promises';
import * as path from 'path';
import { createHash } from 'crypto';
import {
  CaptureScreenshotDto,
  ScreenshotResponseDto,
  ScreenshotFormat,
  ScreenshotType,
} from '../dto/browser-screenshot.dto';
import { BrowserUseService } from '../browser-use.service';
import { BrowserSessionService } from './browser-session.service';

export interface ScreenshotMetadata {
  screenshotId: string;
  sessionId: string;
  taskId?: string;
  capturedAt: Date;
  url: string;
  title: string;
  dimensions: {
    width: number;
    height: number;
    viewportWidth: number;
    viewportHeight: number;
    devicePixelRatio: number;
  };
  fileInfo: {
    format: 'png' | 'jpeg' | 'webp';
    sizeBytes: number;
    path: string;
    hash: string;
  };
  options: {
    fullPage: boolean;
    quality?: number;
    clip?: {
      x: number;
      y: number;
      width: number;
      height: number;
    };
    omitBackground: boolean;
  };
  annotations?: Array<{
    type: 'rectangle' | 'circle' | 'arrow' | 'text';
    coordinates: { x: number; y: number; width?: number; height?: number };
    style: { color: string; thickness: number; fill?: string };
    text?: string;
  }>;
  comparison?: {
    baseScreenshotId: string;
    differenceScore: number;
    differenceAreas: Array<{
      x: number;
      y: number;
      width: number;
      height: number;
      intensity: number;
    }>;
  };
}

@Injectable()
export class BrowserScreenshotService {
  private readonly logger = new Logger(BrowserScreenshotService.name);
  private readonly screenshotsCache = new Map<string, ScreenshotMetadata>();
  private readonly screenshotDirectory: string;
  private readonly maxCacheSize: number;
  private readonly compressionQuality: number;

  constructor(
    private readonly browserUseService: BrowserUseService,
    private readonly sessionService: BrowserSessionService,
    private readonly configService: ConfigService,
  ) {
    this.screenshotDirectory = this.configService.get<string>(
      'BROWSER_SCREENSHOT_DIR',
      path.join(process.cwd(), 'data', 'screenshots'),
    );
    this.maxCacheSize = this.configService.get<number>(
      'BROWSER_SCREENSHOT_CACHE_SIZE',
      1000,
    );
    this.compressionQuality = this.configService.get<number>(
      'BROWSER_SCREENSHOT_QUALITY',
      90,
    );

    this.initializeScreenshotDirectory();
  }

  /**
   * Capture a screenshot from browser session
   */
  async captureScreenshot(
    sessionId: string,
    captureDto: CaptureScreenshotDto,
    taskId?: string,
  ): Promise<ScreenshotResponseDto> {
    const screenshotId = this.generateScreenshotId();
    const timestamp = new Date();

    try {
      this.logger.debug(`Capturing screenshot for session: ${sessionId}`);

      // Validate session exists and is active
      const session = await this.sessionService.getSession(sessionId);
      if (!session) {
        return {
          id: screenshotId,
          data: '',
          format: ScreenshotFormat.PNG,
          type: ScreenshotType.FULLPAGE,
          sizeBytes: 0,
          dimensions: { width: 0, height: 0 },
          metadata: {
            capturedAt: timestamp,
            sessionId,
            url: 'unknown',
            title: 'Error',
            deviceScaleFactor: 1,
          },
          captureDurationMs: 0,
          success: false,
          timestamp,
          sessionId,
          error: {
            code: 'SESSION_NOT_FOUND',
            message: `Browser session ${sessionId} not found`,
            timestamp,
          },
        };
      }

      // Get current page information
      const pageState = await this.browserUseService.getPageState({
        sessionId,
        includeScreenshot: false,
        includeDom: false,
      });

      if (!pageState.success) {
        return {
          id: screenshotId,
          data: '',
          format: ScreenshotFormat.PNG,
          type: ScreenshotType.FULLPAGE,
          sizeBytes: 0,
          dimensions: { width: 0, height: 0 },
          metadata: {
            capturedAt: timestamp,
            sessionId,
            url: 'unknown',
            title: 'Error',
            deviceScaleFactor: 1,
          },
          captureDurationMs: 0,
          success: false,
          timestamp,
          sessionId,
          error: {
            code: 'PAGE_STATE_ERROR',
            message: 'Could not retrieve page state for screenshot',
            timestamp,
          },
        };
      }

      // Capture screenshot using browser-use service
      const screenshotResult = await this.browserUseService.takeScreenshot({
        sessionId,
        fullPage: captureDto.fullPage ?? false,
        quality: captureDto.quality ?? this.compressionQuality,
        format: captureDto.format ?? 'png',
        clip: captureDto.clip,
        omitBackground: captureDto.omitBackground ?? false,
        delay: captureDto.delay,
        hideElements: captureDto.hideElements,
        scrollIntoView: captureDto.scrollIntoView,
      });

      if (!screenshotResult.success || !screenshotResult.screenshotData) {
        return {
          id: screenshotId,
          data: '',
          format: ScreenshotFormat.PNG,
          type: ScreenshotType.FULLPAGE,
          sizeBytes: 0,
          dimensions: { width: 0, height: 0 },
          metadata: {
            capturedAt: timestamp,
            sessionId,
            url: pageState.currentUrl ?? 'unknown',
            title: pageState.pageTitle ?? 'Error',
            deviceScaleFactor: 1,
          },
          captureDurationMs: 0,
          success: false,
          timestamp,
          sessionId,
          error: {
            code: 'CAPTURE_FAILED',
            message: screenshotResult.error ?? 'Screenshot capture failed',
            timestamp,
          },
        };
      }

      // Decode base64 screenshot data
      const screenshotBuffer = Buffer.from(
        screenshotResult.screenshotData,
        'base64',
      );

      // Calculate file hash
      const fileHash = createHash('sha256')
        .update(screenshotBuffer)
        .digest('hex');

      // Generate file path
      const fileName = `${screenshotId}.${captureDto.format ?? 'png'}`;
      const filePath = path.join(this.screenshotDirectory, fileName);

      // Save screenshot to disk
      await fs.writeFile(filePath, screenshotBuffer);

      // Create screenshot metadata
      const metadata: ScreenshotMetadata = {
        screenshotId,
        sessionId,
        taskId,
        capturedAt: timestamp,
        url: pageState.currentUrl ?? 'unknown',
        title: pageState.pageTitle ?? 'Untitled',
        dimensions: {
          width: screenshotResult.dimensions?.width ?? 1280,
          height: screenshotResult.dimensions?.height ?? 720,
          viewportWidth: screenshotResult.viewport?.width ?? 1280,
          viewportHeight: screenshotResult.viewport?.height ?? 720,
          devicePixelRatio: screenshotResult.devicePixelRatio ?? 1,
        },
        fileInfo: {
          format: (captureDto.format ?? 'png') as 'png' | 'jpeg' | 'webp',
          sizeBytes: screenshotBuffer.length,
          path: filePath,
          hash: fileHash,
        },
        options: {
          fullPage: captureDto.fullPage ?? false,
          quality: captureDto.quality,
          clip: captureDto.clip,
          omitBackground: captureDto.omitBackground ?? false,
        },
      };

      // Store in cache
      this.screenshotsCache.set(screenshotId, metadata);
      await this.manageCacheSize();

      // Apply annotations if requested
      if (captureDto.annotations && captureDto.annotations.length > 0) {
        await this.applyAnnotations(screenshotId, captureDto.annotations);
      }

      // Perform comparison if base screenshot provided
      let comparisonResult;
      if (captureDto.compareWith) {
        comparisonResult = await this.compareScreenshots(
          screenshotId,
          captureDto.compareWith,
        );
      }

      this.logger.log(`Screenshot captured successfully: ${screenshotId}`);

      return {
        id: screenshotId,
        data: screenshotResult.screenshotData,
        format: metadata.fileInfo.format as ScreenshotFormat,
        type: ScreenshotType.FULLPAGE,
        sizeBytes: metadata.fileInfo.sizeBytes,
        dimensions: {
          width: metadata.dimensions.width,
          height: metadata.dimensions.height,
        },
        metadata: {
          capturedAt: metadata.capturedAt,
          sessionId: metadata.sessionId,
          url: metadata.url,
          title: metadata.title,
          selector: captureDto.selector,
          quality: captureDto.quality,
          deviceScaleFactor: metadata.dimensions.devicePixelRatio,
        },
        filePath: captureDto.saveToDisk !== false ? filePath : undefined,
        captureDurationMs: 0, // Will be calculated in real implementation
        success: true,
        screenshotId,
        timestamp,
        sessionId,
      };
    } catch (error) {
      this.logger.error(
        `Failed to capture screenshot: ${error.message}`,
        error.stack,
      );

      return {
        id: screenshotId,
        data: '',
        format: ScreenshotFormat.PNG,
        type: ScreenshotType.FULLPAGE,
        sizeBytes: 0,
        dimensions: { width: 0, height: 0 },
        metadata: {
          capturedAt: timestamp,
          sessionId,
          url: 'unknown',
          title: 'Error',
          deviceScaleFactor: 1,
        },
        captureDurationMs: 0,
        success: false,
        timestamp,
        sessionId,
        error: {
          code: 'CAPTURE_ERROR',
          message: error.message,
          details: { sessionId, options: captureDto },
          timestamp,
        },
      };
    }
  }

  /**
   * Retrieve screenshot with proper DTO format for controller endpoint
   */
  async getScreenshot(screenshotId: string): Promise<ScreenshotResponseDto> {
    try {
      const metadata = this.screenshotsCache.get(screenshotId);
      if (!metadata) {
        return {
          id: screenshotId,
          data: '',
          format: ScreenshotFormat.PNG,
          type: ScreenshotType.FULLPAGE,
          sizeBytes: 0,
          dimensions: { width: 0, height: 0 },
          metadata: {
            capturedAt: new Date(),
            sessionId: '',
            url: '',
            title: '',
            deviceScaleFactor: 1,
          },
          captureDurationMs: 0,
          success: false,
          error: {
            code: 'SCREENSHOT_NOT_FOUND',
            message: `Screenshot ${screenshotId} not found`,
          },
        };
      }

      let imageData = '';
      try {
        const buffer = await fs.readFile(metadata.fileInfo.path);
        imageData = buffer.toString('base64');
      } catch (error) {
        this.logger.error(
          `Failed to read screenshot file: ${metadata.fileInfo.path}`,
        );
        return {
          id: screenshotId,
          data: '',
          format: metadata.fileInfo.format as ScreenshotFormat,
          type: ScreenshotType.FULLPAGE,
          sizeBytes: metadata.fileInfo.sizeBytes,
          dimensions: {
            width: metadata.dimensions.width,
            height: metadata.dimensions.height,
          },
          metadata: {
            capturedAt: metadata.capturedAt,
            sessionId: metadata.sessionId,
            url: metadata.url,
            title: metadata.title,
            deviceScaleFactor: metadata.dimensions.devicePixelRatio,
          },
          filePath: metadata.fileInfo.path,
          captureDurationMs: 0,
          success: false,
          error: {
            code: 'FILE_READ_ERROR',
            message: 'Could not read screenshot file',
          },
        };
      }

      return {
        id: screenshotId,
        data: imageData,
        format: metadata.fileInfo.format as ScreenshotFormat,
        type: ScreenshotType.FULLPAGE,
        sizeBytes: metadata.fileInfo.sizeBytes,
        dimensions: {
          width: metadata.dimensions.width,
          height: metadata.dimensions.height,
        },
        metadata: {
          capturedAt: metadata.capturedAt,
          sessionId: metadata.sessionId,
          url: metadata.url,
          title: metadata.title,
          quality: metadata.options.quality,
          deviceScaleFactor: metadata.dimensions.devicePixelRatio,
        },
        filePath: metadata.fileInfo.path,
        captureDurationMs: 0, // Could be calculated from metadata if needed
        success: true,
      };
    } catch (error) {
      this.logger.error(`Error retrieving screenshot: ${error.message}`);
      return {
        id: screenshotId,
        data: '',
        format: ScreenshotFormat.PNG,
        type: ScreenshotType.FULLPAGE,
        sizeBytes: 0,
        dimensions: { width: 0, height: 0 },
        metadata: {
          capturedAt: new Date(),
          sessionId: '',
          url: '',
          title: '',
          deviceScaleFactor: 1,
        },
        captureDurationMs: 0,
        success: false,
        error: {
          code: 'RETRIEVAL_ERROR',
          message: error.message,
        },
      };
    }
  }

  /**
   * Legacy method for internal use - retrieve screenshot metadata and optionally the image data
   */
  async getScreenshotInternal(
    screenshotId: string,
    options?: {
      includeImageData?: boolean;
      format?: 'base64' | 'buffer';
    },
  ): Promise<{
    success: boolean;
    metadata?: ScreenshotMetadata;
    imageData?: string | Buffer;
    error?: { code: string; message: string };
  }> {
    try {
      const metadata = this.screenshotsCache.get(screenshotId);
      if (!metadata) {
        return {
          success: false,
          error: {
            code: 'SCREENSHOT_NOT_FOUND',
            message: `Screenshot ${screenshotId} not found`,
          },
        };
      }

      let imageData: string | Buffer | undefined;

      if (options?.includeImageData) {
        try {
          const buffer = await fs.readFile(metadata.fileInfo.path);

          if (options.format === 'buffer') {
            imageData = buffer;
          } else {
            imageData = buffer.toString('base64');
          }
        } catch (error) {
          this.logger.error(
            `Failed to read screenshot file: ${metadata.fileInfo.path}`,
          );
          return {
            success: false,
            error: {
              code: 'FILE_READ_ERROR',
              message: 'Could not read screenshot file',
            },
          };
        }
      }

      return {
        success: true,
        metadata,
        imageData,
      };
    } catch (error) {
      this.logger.error(`Error retrieving screenshot: ${error.message}`);
      return {
        success: false,
        error: {
          code: 'RETRIEVAL_ERROR',
          message: error.message,
        },
      };
    }
  }

  /**
   * List screenshots with filtering options
   */
  async listScreenshots(filters?: {
    sessionId?: string;
    taskId?: string;
    fromDate?: Date;
    toDate?: Date;
    limit?: number;
  }): Promise<ScreenshotMetadata[]> {
    let screenshots = Array.from(this.screenshotsCache.values());

    if (filters) {
      screenshots = screenshots.filter((screenshot) => {
        if (filters.sessionId && screenshot.sessionId !== filters.sessionId) {
          return false;
        }
        if (filters.taskId && screenshot.taskId !== filters.taskId) {
          return false;
        }
        if (filters.fromDate && screenshot.capturedAt < filters.fromDate) {
          return false;
        }
        if (filters.toDate && screenshot.capturedAt > filters.toDate) {
          return false;
        }
        return true;
      });
    }

    // Sort by capture date (newest first)
    screenshots.sort((a, b) => b.capturedAt.getTime() - a.capturedAt.getTime());

    if (filters?.limit) {
      screenshots = screenshots.slice(0, filters.limit);
    }

    return screenshots;
  }

  /**
   * Compare two screenshots and identify differences
   */
  async compareScreenshots(
    screenshotId1: string,
    screenshotId2: string,
  ): Promise<{
    differenceScore: number;
    differenceAreas: Array<{
      x: number;
      y: number;
      width: number;
      height: number;
      intensity: number;
    }>;
    comparisonScreenshotId?: string;
  }> {
    try {
      // This is a simplified comparison - in production, you'd use a library like Pixelmatch
      const screenshot1 = await this.getScreenshotInternal(screenshotId1, {
        includeImageData: true,
        format: 'buffer',
      });

      const screenshot2 = await this.getScreenshotInternal(screenshotId2, {
        includeImageData: true,
        format: 'buffer',
      });

      if (!screenshot1.success || !screenshot2.success) {
        throw new Error('Could not load screenshots for comparison');
      }

      // Simplified comparison - calculate hash difference
      const hash1 = createHash('sha256')
        .update(screenshot1.imageData as Buffer)
        .digest('hex');
      const hash2 = createHash('sha256')
        .update(screenshot2.imageData as Buffer)
        .digest('hex');

      const differenceScore = hash1 === hash2 ? 0 : 0.5; // Simplified scoring

      // In a real implementation, you would use image processing libraries
      // to detect actual pixel differences and create difference areas
      const differenceAreas: Array<{
        x: number;
        y: number;
        width: number;
        height: number;
        intensity: number;
      }> = [];

      this.logger.debug(
        `Screenshot comparison completed: ${screenshotId1} vs ${screenshotId2} (score: ${differenceScore})`,
      );

      return {
        differenceScore,
        differenceAreas,
      };
    } catch (error) {
      this.logger.error(`Screenshot comparison failed: ${error.message}`);
      throw error;
    }
  }

  /**
   * Apply annotations to a screenshot
   */
  private async applyAnnotations(
    screenshotId: string,
    annotations: Array<{
      type: 'rectangle' | 'circle' | 'arrow' | 'text';
      coordinates: { x: number; y: number; width?: number; height?: number };
      style: { color: string; thickness: number; fill?: string };
      text?: string;
    }>,
  ): Promise<void> {
    const metadata = this.screenshotsCache.get(screenshotId);
    if (!metadata) {
      throw new Error(`Screenshot ${screenshotId} not found`);
    }

    // Store annotations in metadata
    metadata.annotations = annotations.map((annotation) => ({
      type: annotation.type,
      coordinates: annotation.coordinates,
      style: annotation.style,
      text: annotation.text,
    }));

    // In a production implementation, you would use an image processing library
    // to actually draw the annotations on the image file
    this.logger.debug(
      `Applied ${annotations.length} annotations to screenshot: ${screenshotId}`,
    );
  }

  /**
   * Delete a screenshot and its associated files
   */
  async deleteScreenshot(screenshotId: string): Promise<boolean> {
    try {
      const metadata = this.screenshotsCache.get(screenshotId);
      if (!metadata) {
        return false;
      }

      // Delete file from disk
      try {
        await fs.unlink(metadata.fileInfo.path);
      } catch (error) {
        this.logger.warn(
          `Could not delete screenshot file: ${metadata.fileInfo.path}`,
        );
      }

      // Remove from cache
      this.screenshotsCache.delete(screenshotId);

      this.logger.debug(`Screenshot deleted: ${screenshotId}`);
      return true;
    } catch (error) {
      this.logger.error(`Failed to delete screenshot: ${error.message}`);
      return false;
    }
  }

  /**
   * Get screenshot service statistics
   */
  async getStatistics(): Promise<{
    totalScreenshots: number;
    totalSizeBytes: number;
    averageSizeBytes: number;
    formatDistribution: Record<string, number>;
    oldestScreenshot?: Date;
    newestScreenshot?: Date;
    diskUsage: {
      totalSizeBytes: number;
      totalFiles: number;
    };
  }> {
    const screenshots = Array.from(this.screenshotsCache.values());

    const totalSizeBytes = screenshots.reduce(
      (sum, s) => sum + s.fileInfo.sizeBytes,
      0,
    );
    const averageSizeBytes =
      screenshots.length > 0 ? totalSizeBytes / screenshots.length : 0;

    const formatDistribution: Record<string, number> = {};
    screenshots.forEach((s) => {
      formatDistribution[s.fileInfo.format] =
        (formatDistribution[s.fileInfo.format] || 0) + 1;
    });

    const dates = screenshots.map((s) => s.capturedAt).sort();
    const oldestScreenshot = dates.length > 0 ? dates[0] : undefined;
    const newestScreenshot =
      dates.length > 0 ? dates[dates.length - 1] : undefined;

    // Calculate disk usage
    let diskTotalSize = 0;
    let diskTotalFiles = 0;

    try {
      const files = await fs.readdir(this.screenshotDirectory);
      diskTotalFiles = files.length;

      for (const file of files) {
        try {
          const stats = await fs.stat(
            path.join(this.screenshotDirectory, file),
          );
          diskTotalSize += stats.size;
        } catch (error) {
          // Skip files that can't be read
        }
      }
    } catch (error) {
      this.logger.warn(`Could not read screenshot directory: ${error.message}`);
    }

    return {
      totalScreenshots: screenshots.length,
      totalSizeBytes,
      averageSizeBytes: Math.round(averageSizeBytes),
      formatDistribution,
      oldestScreenshot,
      newestScreenshot,
      diskUsage: {
        totalSizeBytes: diskTotalSize,
        totalFiles: diskTotalFiles,
      },
    };
  }

  /**
   * Private helper methods
   */
  private generateScreenshotId(): string {
    return `screenshot_${Date.now()}_${Math.random().toString(36).substring(2, 15)}`;
  }

  private async initializeScreenshotDirectory(): Promise<void> {
    try {
      await fs.access(this.screenshotDirectory);
    } catch (error) {
      // Directory doesn't exist, create it
      await fs.mkdir(this.screenshotDirectory, { recursive: true });
      this.logger.log(
        `Created screenshots directory: ${this.screenshotDirectory}`,
      );
    }
  }

  private async manageCacheSize(): Promise<void> {
    if (this.screenshotsCache.size <= this.maxCacheSize) {
      return;
    }

    // Remove oldest screenshots from cache (not from disk)
    const screenshots = Array.from(this.screenshotsCache.values());
    screenshots.sort((a, b) => a.capturedAt.getTime() - b.capturedAt.getTime());

    const toRemove = screenshots.slice(
      0,
      this.screenshotsCache.size - this.maxCacheSize,
    );
    toRemove.forEach((screenshot) => {
      this.screenshotsCache.delete(screenshot.screenshotId);
    });

    this.logger.debug(`Removed ${toRemove.length} screenshots from cache`);
  }

  /**
   * Cleanup on service destruction
   */
  async onModuleDestroy(): Promise<void> {
    this.logger.log('Screenshot service cleanup completed');
  }
}

/**
 * Browser Session Service
 *
 * Manages browser session lifecycle including creation, monitoring, and cleanup.
 * Integrates with the browser-use framework to provide session management
 * with enterprise-grade monitoring and local-only architecture compliance.
 */

import {
  Injectable,
  Logger,
  NotFoundException,
  ConflictException,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { BrowserUseService } from '../browser-use.service';
import {
  CreateBrowserSessionDto,
  BrowserSessionResponseDto,
  BrowserSessionListResponseDto,
  BrowserSessionStatus,
  BrowserTabInfo,
  BrowserSessionMetrics,
} from '../dto/browser-session.dto';
import { randomUUID } from 'crypto';
import { join } from 'path';

interface SessionData {
  id: string;
  name: string;
  description?: string;
  status: BrowserSessionStatus;
  profile: any;
  timeoutSeconds: number;
  enableScreenshots: boolean;
  enableVideoRecording: boolean;
  enableNetworkLogging: boolean;
  enableConsoleLogging: boolean;
  tags?: string[];
  createdAt: Date;
  lastActivity: Date;
  expiresAt: Date;
  createdBy: string;
  currentUrl?: string;
  currentTitle?: string;
  tabs: BrowserTabInfo[];
  metrics: BrowserSessionMetrics;
  processId?: string;
  websocketUrl?: string;
  config?: Record<string, any>;
  error?: any;
}

@Injectable()
export class BrowserSessionService {
  private readonly logger = new Logger(BrowserSessionService.name);
  private readonly sessions = new Map<string, SessionData>();
  private readonly sessionTimeouts = new Map<string, NodeJS.Timeout>();

  constructor(
    private readonly configService: ConfigService,
    private readonly browserUseService: BrowserUseService,
  ) {}

  /**
   * Create a new browser session
   */
  async createSession(
    createDto: CreateBrowserSessionDto,
  ): Promise<BrowserSessionResponseDto> {
    const sessionId = randomUUID();
    const currentTime = new Date();

    this.logger.log(
      `Creating browser session: ${sessionId} (${createDto.name})`,
    );

    try {
      // Create browser process through browser-use service
      const processId = await this.browserUseService.createBrowserProcess(
        'session',
        sessionId,
        {
          ...createDto.profile,
          headless: createDto.profile?.headless ?? true,
          screenshots: createDto.enableScreenshots,
          videoRecording: createDto.enableVideoRecording,
          networkLogging: createDto.enableNetworkLogging,
          consoleLogging: createDto.enableConsoleLogging,
          timeout: createDto.timeoutSeconds * 1000,
        },
      );

      // Initialize session data
      const sessionData: SessionData = {
        id: sessionId,
        name: createDto.name,
        description: createDto.description,
        status: BrowserSessionStatus.INITIALIZING,
        profile: createDto.profile || {},
        timeoutSeconds: createDto.timeoutSeconds || 600,
        enableScreenshots: createDto.enableScreenshots ?? true,
        enableVideoRecording: createDto.enableVideoRecording ?? false,
        enableNetworkLogging: createDto.enableNetworkLogging ?? true,
        enableConsoleLogging: createDto.enableConsoleLogging ?? true,
        tags: createDto.tags,
        createdAt: currentTime,
        lastActivity: currentTime,
        expiresAt: new Date(
          currentTime.getTime() + (createDto.timeoutSeconds || 600) * 1000,
        ),
        createdBy: 'system', // TODO: Get from auth context
        currentUrl: createDto.initialUrl,
        tabs: [],
        metrics: this.initializeSessionMetrics(),
        processId,
        config: createDto.config,
      };

      // Store session
      this.sessions.set(sessionId, sessionData);

      // Setup session timeout
      this.setupSessionTimeout(sessionId);

      // Navigate to initial URL if provided
      if (createDto.initialUrl) {
        await this.navigateToInitialUrl(sessionId, createDto.initialUrl);
      }

      // Update status to active
      sessionData.status = BrowserSessionStatus.ACTIVE;

      this.logger.log(`Browser session created successfully: ${sessionId}`);

      return this.mapToResponseDto(sessionData);
    } catch (error) {
      this.logger.error(
        `Failed to create browser session: ${sessionId}`,
        error,
      );

      // Cleanup on failure
      if (this.sessions.has(sessionId)) {
        await this.cleanupSession(sessionId);
      }

      throw new ConflictException(
        `Failed to create browser session: ${error.message}`,
      );
    }
  }

  /**
   * Get session by ID
   */
  async getSession(sessionId: string): Promise<BrowserSessionResponseDto> {
    const sessionData = this.sessions.get(sessionId);
    if (!sessionData) {
      throw new NotFoundException(`Browser session not found: ${sessionId}`);
    }

    // Update session activity
    sessionData.lastActivity = new Date();

    // Refresh session data from browser process
    await this.refreshSessionData(sessionData);

    return this.mapToResponseDto(sessionData);
  }

  /**
   * List all sessions
   */
  async listSessions(
    filters: { active?: boolean } = {},
  ): Promise<BrowserSessionListResponseDto> {
    let sessions = Array.from(this.sessions.values());

    // Apply filters
    if (filters.active !== undefined) {
      const activeStatuses = [
        BrowserSessionStatus.ACTIVE,
        BrowserSessionStatus.IDLE,
      ];
      sessions = sessions.filter((session) =>
        filters.active
          ? activeStatuses.includes(session.status)
          : !activeStatuses.includes(session.status),
      );
    }

    // Refresh data for active sessions
    await Promise.all(
      sessions
        .filter((session) => session.status === BrowserSessionStatus.ACTIVE)
        .map((session) => this.refreshSessionData(session)),
    );

    const responseSessions = sessions.map((session) =>
      this.mapToResponseDto(session),
    );

    // Calculate summary statistics
    const summary = this.calculateSessionSummary(sessions);

    return {
      sessions: responseSessions,
      total: sessions.length,
      activeCount: sessions.filter(
        (s) => s.status === BrowserSessionStatus.ACTIVE,
      ).length,
      idleCount: sessions.filter((s) => s.status === BrowserSessionStatus.IDLE)
        .length,
      errorCount: sessions.filter(
        (s) => s.status === BrowserSessionStatus.ERROR,
      ).length,
      totalMemoryUsageMB: sessions.reduce(
        (total, s) => total + s.metrics.memoryUsageMB,
        0,
      ),
      summary,
    };
  }

  /**
   * Close a specific session
   */
  async closeSession(sessionId: string): Promise<void> {
    const sessionData = this.sessions.get(sessionId);
    if (!sessionData) {
      throw new NotFoundException(`Browser session not found: ${sessionId}`);
    }

    this.logger.log(`Closing browser session: ${sessionId}`);

    try {
      sessionData.status = BrowserSessionStatus.CLOSING;

      // Cleanup browser process
      if (sessionData.processId) {
        await this.browserUseService.cleanupProcess(sessionData.processId);
      }

      await this.cleanupSession(sessionId);

      this.logger.log(`Browser session closed successfully: ${sessionId}`);
    } catch (error) {
      this.logger.error(`Failed to close browser session: ${sessionId}`, error);
      sessionData.status = BrowserSessionStatus.ERROR;
      sessionData.error = {
        message: error.message,
        code: 'CLOSE_ERROR',
        timestamp: new Date(),
      };
      throw error;
    }
  }

  /**
   * Close all sessions
   */
  async closeAllSessions(): Promise<void> {
    this.logger.log('Closing all browser sessions');

    const sessionIds = Array.from(this.sessions.keys());
    const closePromises = sessionIds.map((sessionId) =>
      this.closeSession(sessionId).catch((error) =>
        this.logger.error(`Failed to close session ${sessionId}`, error),
      ),
    );

    await Promise.all(closePromises);

    this.logger.log('All browser sessions closed');
  }

  /**
   * Update session activity timestamp
   */
  updateSessionActivity(sessionId: string): void {
    const sessionData = this.sessions.get(sessionId);
    if (sessionData) {
      sessionData.lastActivity = new Date();

      // Reset timeout
      this.setupSessionTimeout(sessionId);
    }
  }

  /**
   * Get session metrics
   */
  getSessionMetrics(sessionId: string): BrowserSessionMetrics | null {
    const sessionData = this.sessions.get(sessionId);
    return sessionData ? sessionData.metrics : null;
  }

  /**
   * Navigate to initial URL after session creation
   */
  private async navigateToInitialUrl(
    sessionId: string,
    url: string,
  ): Promise<void> {
    try {
      const sessionData = this.sessions.get(sessionId);
      if (!sessionData || !sessionData.processId) {
        return;
      }

      // Send navigation command to browser process
      await this.browserUseService.sendCommand(sessionData.processId, {
        action: 'navigate',
        url: url,
      });

      sessionData.currentUrl = url;
      sessionData.lastActivity = new Date();
    } catch (error) {
      this.logger.warn(`Failed to navigate to initial URL: ${url}`, error);
    }
  }

  /**
   * Refresh session data from browser process
   */
  private async refreshSessionData(sessionData: SessionData): Promise<void> {
    if (!sessionData.processId) return;

    try {
      // Get current browser state
      const browserState = await this.browserUseService.sendCommand(
        sessionData.processId,
        {
          action: 'get_state',
          include_tabs: true,
          include_metrics: true,
        },
      );

      if (browserState.success) {
        // Update current URL and title
        sessionData.currentUrl = browserState.url;
        sessionData.currentTitle = browserState.title;

        // Update tabs information
        if (browserState.tabs) {
          sessionData.tabs = browserState.tabs.map((tab) => ({
            id: tab.id,
            title: tab.title || '',
            url: tab.url || '',
            active: tab.active || false,
            createdAt: new Date(tab.createdAt || Date.now()),
            lastActivity: new Date(tab.lastActivity || Date.now()),
            loadingStatus: tab.loadingStatus || 'complete',
          }));
        }

        // Update metrics
        if (browserState.metrics) {
          this.updateSessionMetrics(sessionData, browserState.metrics);
        }

        // Update status based on activity
        const timeSinceActivity =
          Date.now() - sessionData.lastActivity.getTime();
        if (timeSinceActivity > 300000) {
          // 5 minutes
          sessionData.status = BrowserSessionStatus.IDLE;
        } else {
          sessionData.status = BrowserSessionStatus.ACTIVE;
        }
      }
    } catch (error) {
      this.logger.debug(
        `Failed to refresh session data: ${sessionData.id}`,
        error,
      );
      // Don't throw error - session might be in transition state
    }
  }

  /**
   * Update session metrics with new data
   */
  private updateSessionMetrics(sessionData: SessionData, metrics: any): void {
    const currentTime = Date.now();
    const sessionDuration =
      (currentTime - sessionData.createdAt.getTime()) / 1000;

    sessionData.metrics = {
      totalDurationSeconds: sessionDuration,
      pagesVisited: metrics.pagesVisited || sessionData.metrics.pagesVisited,
      actionsPerformed:
        metrics.actionsPerformed || sessionData.metrics.actionsPerformed,
      screenshotsTaken:
        metrics.screenshotsTaken || sessionData.metrics.screenshotsTaken,
      errorsEncountered:
        metrics.errorsEncountered || sessionData.metrics.errorsEncountered,
      networkRequests:
        metrics.networkRequests || sessionData.metrics.networkRequests,
      dataTransferredBytes:
        metrics.dataTransferredBytes ||
        sessionData.metrics.dataTransferredBytes,
      averagePageLoadTime:
        metrics.averagePageLoadTime || sessionData.metrics.averagePageLoadTime,
      memoryUsageMB: metrics.memoryUsageMB || sessionData.metrics.memoryUsageMB,
      cpuUsagePercent:
        metrics.cpuUsagePercent || sessionData.metrics.cpuUsagePercent,
    };
  }

  /**
   * Initialize session metrics
   */
  private initializeSessionMetrics(): BrowserSessionMetrics {
    return {
      totalDurationSeconds: 0,
      pagesVisited: 0,
      actionsPerformed: 0,
      screenshotsTaken: 0,
      errorsEncountered: 0,
      networkRequests: 0,
      dataTransferredBytes: 0,
      averagePageLoadTime: 0,
      memoryUsageMB: 0,
      cpuUsagePercent: 0,
    };
  }

  /**
   * Setup session timeout
   */
  private setupSessionTimeout(sessionId: string): void {
    // Clear existing timeout
    const existingTimeout = this.sessionTimeouts.get(sessionId);
    if (existingTimeout) {
      clearTimeout(existingTimeout);
    }

    const sessionData = this.sessions.get(sessionId);
    if (!sessionData) return;

    // Set new timeout
    const timeout = setTimeout(async () => {
      this.logger.log(`Session timeout reached: ${sessionId}`);
      await this.closeSession(sessionId).catch((error) =>
        this.logger.error(
          `Failed to close timed-out session: ${sessionId}`,
          error,
        ),
      );
    }, sessionData.timeoutSeconds * 1000);

    this.sessionTimeouts.set(sessionId, timeout);
  }

  /**
   * Cleanup session resources
   */
  private async cleanupSession(sessionId: string): Promise<void> {
    const sessionData = this.sessions.get(sessionId);
    if (!sessionData) return;

    // Clear timeout
    const timeout = this.sessionTimeouts.get(sessionId);
    if (timeout) {
      clearTimeout(timeout);
      this.sessionTimeouts.delete(sessionId);
    }

    // Update final status
    sessionData.status = BrowserSessionStatus.CLOSED;

    // Remove from active sessions after delay (keep for history)
    setTimeout(() => {
      this.sessions.delete(sessionId);
    }, 60000); // Keep for 1 minute for potential queries
  }

  /**
   * Calculate session summary statistics
   */
  private calculateSessionSummary(sessions: SessionData[]): any {
    const activeSessions = sessions.filter(
      (s) => s.status === BrowserSessionStatus.ACTIVE,
    ).length;
    const idleSessions = sessions.filter(
      (s) => s.status === BrowserSessionStatus.IDLE,
    ).length;
    const closedSessions = sessions.filter(
      (s) => s.status === BrowserSessionStatus.CLOSED,
    ).length;

    const totalDuration = sessions.reduce(
      (total, s) => total + s.metrics.totalDurationSeconds,
      0,
    );
    const averageSessionDuration =
      sessions.length > 0 ? totalDuration / sessions.length : 0;

    const peakMemoryUsage = Math.max(
      ...sessions.map((s) => s.metrics.memoryUsageMB),
      0,
    );

    return {
      totalSessions: sessions.length,
      activeSessions,
      idleSessions,
      closedSessions,
      averageSessionDuration,
      peakMemoryUsage,
    };
  }

  /**
   * Map session data to response DTO
   */
  private mapToResponseDto(
    sessionData: SessionData,
  ): BrowserSessionResponseDto {
    return {
      id: sessionData.id,
      name: sessionData.name,
      description: sessionData.description,
      success: sessionData.status !== BrowserSessionStatus.ERROR,
      status: sessionData.status,
      profile: sessionData.profile,
      timeoutSeconds: sessionData.timeoutSeconds,
      enableScreenshots: sessionData.enableScreenshots,
      enableVideoRecording: sessionData.enableVideoRecording,
      enableNetworkLogging: sessionData.enableNetworkLogging,
      enableConsoleLogging: sessionData.enableConsoleLogging,
      tags: sessionData.tags,
      createdAt: sessionData.createdAt,
      lastActivity: sessionData.lastActivity,
      expiresAt: sessionData.expiresAt,
      createdBy: sessionData.createdBy,
      currentUrl: sessionData.currentUrl,
      currentTitle: sessionData.currentTitle,
      tabs: sessionData.tabs,
      activeTabsCount: sessionData.tabs.filter((tab) => tab.active).length,
      metrics: sessionData.metrics,
      processId: sessionData.processId,
      websocketUrl: sessionData.websocketUrl,
      config: sessionData.config,
      error: sessionData.error,
    };
  }
}

